import{_ as e,o as d,c as i,a0 as o}from"./chunks/framework.BtostX_-.js";const k=JSON.parse('{"title":"单链表","description":"","frontmatter":{"title":"单链表","icon":"link"},"headers":[],"relativePath":"zh/notes/linkedlist.md","filePath":"zh/notes/linkedlist.md","lastUpdated":1793616665000}'),a={name:"zh/notes/linkedlist.md"};function s(n,t,l,r,c,h){return d(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="单链表" tabindex="-1">单链表 <a class="header-anchor" href="#单链表" aria-label="Permalink to &quot;单链表&quot;">​</a></h1><blockquote><p><a href="/algorithms/notes/linkedlist.html">English</a> | <strong>中文</strong></p></blockquote><p><code>linkedlist/go</code> 模块实现带头哨兵节点的单链表，读写锁保护。</p><h2 id="实现位置" tabindex="-1">实现位置 <a class="header-anchor" href="#实现位置" aria-label="Permalink to &quot;实现位置&quot;">​</a></h2><ul><li>源码：<code>linkedlist/go/linkedlist.go</code></li><li>测试：<code>linkedlist/go/linkedlist_test.go</code>（11 个测试函数）</li></ul><h2 id="接口" tabindex="-1">接口 <a class="header-anchor" href="#接口" aria-label="Permalink to &quot;接口&quot;">​</a></h2><p>构造函数：<code>NewLinkedList()</code>（带头哨兵节点的链表）。</p><table tabindex="0"><thead><tr><th>方法</th><th>说明</th></tr></thead><tbody><tr><td><code>AddFirst / AddLast</code></td><td>头插 / 尾插</td></tr><tr><td><code>GetFirst / GetLast</code></td><td>读首 / 读尾</td></tr><tr><td><code>RemoveFirst / RemoveLast</code></td><td>删首 / 删尾，空表返回 nil</td></tr><tr><td><code>Insert(index, element)</code></td><td>1 基下标插入；合法区间 <code>[1, size+1]</code>（1 为头插，<code>size+1</code> 为尾插）；返回 <code>error</code>，越界返回 <code>ErrIndexOutOfRange</code></td></tr><tr><td><code>DeleteByIndex(index)</code></td><td>按下标删除，越界不动作</td></tr><tr><td><code>DeleteByBottomIndex(index)</code></td><td>删倒数第 N 个（快慢指针）</td></tr><tr><td><code>Contains(element)</code></td><td>是否包含</td></tr><tr><td><code>Reverse()</code></td><td>原地反转</td></tr><tr><td><code>HasCycle()</code></td><td>快慢指针判环</td></tr><tr><td><code>FindMiddleNode()</code></td><td>快慢指针取中点；偶数长度返回前一个中点</td></tr><tr><td><code>Size / IsEmpty / String</code></td><td>常规</td></tr></tbody></table><h2 id="历史坑位-已修复-回归用例在测试里" tabindex="-1">历史坑位（已修复，回归用例在测试里） <a class="header-anchor" href="#历史坑位-已修复-回归用例在测试里" aria-label="Permalink to &quot;历史坑位（已修复，回归用例在测试里）&quot;">​</a></h2><ul><li><strong>String</strong>：遍历忘了 <code>cur = cur.next</code>，死循环。</li><li><strong>Contains</strong>：循环条件 <code>next.next != nil</code> 漏判尾节点。</li><li><strong>HasCycle</strong>：条件缺 <code>fast != nil</code>，单节点链表 <code>nil.next</code> panic。</li><li><strong>FindMiddleNode</strong>：<code>fast.next.next</code> 未判空，偶数长度 panic。</li><li><strong>Insert</strong>：持 <code>RLock</code> 写链表（数据竞争），已改 <code>Lock</code>，<code>-race</code> 验证通过。</li></ul><h2 id="测试状态" tabindex="-1">测试状态 <a class="header-anchor" href="#测试状态" aria-label="Permalink to &quot;测试状态&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linkedlist/go</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -race</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./...</span></span></code></pre></div><p>当前 11 个测试全部通过（含手工构造的带环链表与偶数长度取中点用例）。</p>',13)])])}const g=e(a,[["render",s]]);export{k as __pageData,g as default};
